import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Scanner;

public class Solution {
    public static BigDecimal calculateInterest(BigDecimal principal, BigDecimal rate, BigDecimal time) {
        return principal.multiply(rate).multiply(time)
                .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNext()) return;
        BigDecimal p = new BigDecimal(sc.next());
        BigDecimal r = new BigDecimal(sc.next());
        BigDecimal t = new BigDecimal(sc.next());
        System.out.println(calculateInterest(p, r, t).setScale(2, RoundingMode.HALF_UP).toPlainString());
    }
}

