import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        boolean isNeg = n < 0;
        long num = Math.abs((long)n);
        long rev = 0;
        while (num > 0) {
            rev = rev * 10 + (num % 10);
            num /= 10;
        }
        if (isNeg) rev = -rev;
        System.out.println(rev);
    }
}

