class CircularQueue {
    private int[] data;
    private int head = -1, tail = -1, size;

    public CircularQueue(int k) { data = new int[k]; size = k; }
    public boolean enQueue(int value) {
        if ((tail + 1) % size == head) return false;
        if (head == -1) head = 0;
        tail = (tail + 1) % size;
        data[tail] = value;
        return true;
    }
    public boolean deQueue() {
        if (head == -1) return false;
        if (head == tail) { head = -1; tail = -1; }
        else head = (head + 1) % size;
        return true;
    }
    public int Front() { return head == -1 ? -1 : data[head]; }
}

